codes.java:
// assumption stated aloud, then captured in the design
// "I will assume one ticket maps to exactly one vehicle."
class Vehicle {
    String plate;
    Vehicle(String plate) { this.plate = plate; }
}

class Ticket {
    private Vehicle vehicle;   // one vehicle per ticket

    Ticket(Vehicle vehicle) {
        this.vehicle = vehicle;
    }

    Vehicle getVehicle() {
        return vehicle;
    }
}

public class Main {
    public static void main(String[] args) {
        Vehicle vehicle = new Vehicle("KA-01-HH-1234");
        Ticket ticket = new Ticket(vehicle);

        System.out.println("Ticket issued for vehicle: " + ticket.getVehicle().plate);
    }
}

codes.cpp:
#include <iostream>
#include <string>

// assumption stated aloud, then captured in the design
// "I will assume one ticket maps to exactly one vehicle."
class Vehicle {
public:
    std::string plate;
    Vehicle(std::string plate) : plate(plate) {}
};

class Ticket {
private:
    Vehicle vehicle;   // one vehicle per ticket

public:
    Ticket(Vehicle vehicle) : vehicle(vehicle) {}

    Vehicle getVehicle() const {
        return vehicle;
    }
};

int main() {
    Vehicle vehicle("KA-01-HH-1234");
    Ticket ticket(vehicle);

    std::cout << "Ticket issued for vehicle: " << ticket.getVehicle().plate << std::endl;

    return 0;
}

